183	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
184	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
185	        if (claim.getStatus() != ClaimStatus.DRAFT) {
186	            throw new ClaimNotEditableException(claim.getStatus());
187	        }
188	        if (claim.lockedAgainst(user)) {
189	            throw new ClaimLockedException(claim.getLockedBy());
190	        }
191	        LocalDate on = date != null ? date : settings.defaultClaimDate(sheetId);
192	        refuseClosed(sheetId, claim.getDueBy());
193	        refuseRetired(person, on);
194	        refuseBadCorrection(sheetId, personId, amount, corrects, claim.getId());
195	        ref = refOf(ref);
196	        refuseRefInUse(sheetId, ref, claim.getId());
197	        refuseRelined(claim, scaled(amount));
198	        claim.setAmount(scaled(amount));
199	        claim.setRef(ref);
200	        claim.setTags(tagsOf(tags));
201	        claim.setCorrects(corrects);
202	        claim.setDate(on);
203	        claim.setNote(noteOf(note));
204	        claim.setLockedBy(null);
205	        claim.setEditedBy(user);
206	        Claim saved = claims.saveAndFlush(claim);
207	        useTags(sheetId, saved);
208	        record("CLAIM_EDITED", sheetId, user, person, saved);
209	        return saved;
210	    }
