213	     *  the unit amounts of its lines added up, and CLAIM_LINE_ADDED is written ending with the line. A
214	     *  claim that is not a DRAFT, a correction, one due by a day in a closed period, one another user's
215	     *  editor locks, a blank label, a quantity below 1 or a negative unit amount, is refused. */
216	    @Transactional
217	    public Claim addLine(String sheetId, String user, Long personId, Long id, String label, int qty,
218	            BigDecimal unit) {
219	        Person person = person(sheetId, personId);
220	        sheets.lock(sheetId);
221	        Claim claim = claim(sheetId, personId, id);
222	        if (claim.getStatus() != ClaimStatus.DRAFT) {
223	            throw new ClaimNotEditableException(claim.getStatus());
224	        }
225	        refuseClosed(sheetId, claim.getDueBy());
226	        if (claim.lockedAgainst(user)) {
227	            throw new ClaimLockedException(claim.getLockedBy());
