360	    private Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
361	            String voidReason, boolean judgedOnOriginal) {
362	        return changeStatus(sheetId, user, personId, id, to, voidReason, judgedOnOriginal, null);
