364	
365	    private Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to,
366	            String voidReason, boolean judgedOnOriginal, LocalDate settledOn) {
367	        Person person = person(sheetId, personId);
368	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
369	        // read below is its latest state.
370	        if (to == ClaimStatus.OPEN) {
371	            sheets.lock(sheetId);
372	        }
373	        Claim claim = claim(sheetId, personId, id);
374	        settings.refuseUnless(sheetId, user, switch (to) {
375	            case OPEN -> Permission.OPEN;
376	            case SETTLED -> Permission.SETTLE;
377	            case VOID -> Permission.VOID;
378	            case DRAFT, PENDING, DELETED, REVIEW -> throw new StatusChangeRefusedException(claim.getStatus(), to);
379	        });
380	        // While the person's flag is in force only a steward opens their claims.
381	        if (to == ClaimStatus.OPEN && person.flaggedOn(sheets.today(sheetId))
382	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
383	            throw new PermissionRefusedException(user, Permission.OPEN);
384	        }
385	        refuseClosed(sheetId, claim.getDueBy());
386	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
387	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
388	        if (reversing) {
389	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
390	        } else if (!claim.getStatus().canMoveTo(to)) {
391	            throw new StatusChangeRefusedException(claim.getStatus(), to);
392	        }
393	        String reason = voidReason == null || voidReason.isBlank() ? null : voidReason.trim();
394	        if (to == ClaimStatus.VOID) {
395	            refuseUnreasonedVoid(sheetId, reason);
396	        }
397	        if (to == ClaimStatus.SETTLED && !judgedOnOriginal && claim.openedOrEditedBy(user)) {
398	            throw new OwnClaimSettleRefusedException(user);
399	        }
400	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
401	            throw new StatusChangeRefusedException(claim.getStatus(), to);
402	        }
403	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
404	        // gathered by then.
405	        BigDecimal due = to == ClaimStatus.SETTLED ? settleDueOf(sheetId, person, claim, settledOn) : null;
406	        if (to == ClaimStatus.SETTLED && !judgedOnOriginal) {
407	            refuseUnproved(sheetId, person, claim, due);
408	        }
409	        if (to == ClaimStatus.OPEN) {
410	            refuseUnnoted(sheetId, person, claim);
411	            refuseOverCap(sheetId, claim);
412	        }
413	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, person, user, due)) {
414	            to = ClaimStatus.PENDING;
415	        }
416	        if (to == ClaimStatus.OPEN && overReviewThreshold(sheetId, person, claim)) {
417	            to = ClaimStatus.REVIEW;
418	        }
419	        claim.setStatus(to);
420	        if (to == ClaimStatus.SETTLED || to == ClaimStatus.PENDING) {
421	            // Settled one at a time until a bulk settle marks it with its batch.
422	            claim.setBatch(null);
423	        }
424	        if (to == ClaimStatus.OPEN) {
425	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
426	            claim.setOpenedBy(user);
427	        } else if (to == ClaimStatus.REVIEW) {
428	            // Numbered only once a steward has reviewed it.
429	            claim.setOpenedBy(user);
430	        } else if (to == ClaimStatus.SETTLED) {
431	            claim.setSettledDue(due);
432	        } else if (to == ClaimStatus.VOID) {
433	            claim.setVoidReason(reason);
434	        }
435	        Claim saved = claims.saveAndFlush(claim);
436	        log(sheetId, user, person, saved);
437	        String event = switch (to) {
438	            case OPEN -> "CLAIM_OPENED";
439	            case PENDING -> "CLAIM_PENDING";
440	            case REVIEW -> "CLAIM_REVIEW";
441	            case SETTLED -> "CLAIM_SETTLED";
442	            case VOID -> "CLAIM_VOIDED";
443	            case DRAFT, DELETED -> throw new IllegalStateException("A claim is deleted or restored on its own");
444	        };
445	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
446	        if (to == ClaimStatus.SETTLED) {
447	            line += " due=" + settledDueText(saved);
448	            if (settledOn != null) {
449	                line += " on=" + settledOn;
450	            }
451	        } else if (reversing) {
452	            line += " reversed=" + settledDueText(saved);
453	        }
454	        if (to == ClaimStatus.VOID && reason != null) {
455	            line += " reason=" + reason;
456	        }
457	        audit.recordOnCommit(line);
458	        if (to == ClaimStatus.SETTLED) {
459	            notifyWatchers(sheetId, user, person, saved);
460	        }
461	        return saved;
462	    }
