464	    /** The due a claim is settled at: as it stands now, or (a date given) as it stood at the end of
465	     *  that day; a date after the sheet's today, or one the claim had not been added by, is refused. */
466	    private BigDecimal settleDueOf(String sheetId, Person person, Claim claim, LocalDate on) {
467	        if (on == null) {
468	            return dueOf(sheetId, person, claim);
469	        }
470	        if (on.isAfter(sheets.today(sheetId))) {
471	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
472	        }
473	        Claim then = history.claim(claim.getId(), on)
474	                .orElseThrow(() -> new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED));
475	        return dueOf(sheetId, person, then, on);
476	    }
