501	    /** Restore a DELETED claim to a DRAFT, on the sheet's today it was deleted: its status log gains a
502	     *  DRAFT line and CLAIM_RESTORED is written. Any other claim, a later day, or a claim dated in a
503	     *  closed period, is refused. */
504	    @Transactional
505	    public Claim restore(String sheetId, String user, Long personId, Long id) {
506	        Person person = person(sheetId, personId);
507	        sheets.lock(sheetId);
