553	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
554	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
555	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
556	     *  is listed under the person naming the claim it was split from (a late entry when its due-by falls
557	     *  in a soft-closed period). A claim that is not OPEN, one
558	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
559	     *  user whose role may not open a claim, is refused. */
560	    @Transactional
561	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
562	        Person person = person(sheetId, personId);
563	        // Lock the sheet first, as opening does: the new claim takes the next number.
564	        sheets.lock(sheetId);
565	        Claim claim = claim(sheetId, personId, id);
566	        settings.refuseUnless(sheetId, user, Permission.OPEN);
567	        refuseClosed(sheetId, claim.getDueBy());
568	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
569	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
570	        }
571	        BigDecimal part = scaled(amount);
572	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
573	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
574	        }
575	        claim.setAmount(claim.getAmount().subtract(part));
576	        claim.unbind();
577	        Claim kept = claims.saveAndFlush(claim);
578	        LocalDate on = kept.getDate();
579	        int terms = termsFor(sheetId, person, sheets.today(sheetId));
580	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
581	        Claim split = Claim.splitOff(kept, part, dueBy, terms, nextNumber(sheetId, dueBy), user);
582	        if (periods.softClosedOn(sheetId, dueBy)) {
583	            split.markLateEntry();
584	        }
585	        Claim added = claims.saveAndFlush(split);
586	        log(sheetId, user, person, added);
587	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
588	                + " into=" + added.getNumber());
589	        record("CLAIM_OPENED", sheetId, user, person, added);
590	        return new Split(kept, added);
591	    }
