603	        refuseUnproved(sheetId, person, claim, due);
604	        claim.setSettledDue(due);
605	        claim.setStatus(ClaimStatus.SETTLED);
606	        Claim saved = claims.saveAndFlush(claim);
607	        log(sheetId, user, person, saved);
608	        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
609	                + " due=" + settledDueText(saved));
610	        notifyWatchers(sheetId, user, person, saved);
611	        return saved;
612	    }
