614	    /** A steward reviews a REVIEW claim: it is OPEN, taking the next number as an opened claim does, and
615	     *  keeps who opened it; CLAIM_REVIEWED then CLAIM_OPENED are written. Anyone else, a claim that is
616	     *  not in REVIEW, or one dated in a closed period, is refused. */
617	    @Transactional
618	    public Claim review(String sheetId, String user, Long personId, Long id) {
619	        Person person = person(sheetId, personId);
620	        // Lock the sheet first, as opening does: the claim takes the next number.
621	        sheets.lock(sheetId);
622	        Claim claim = claim(sheetId, personId, id);
623	        refuseClosed(sheetId, claim.getDueBy());
624	        if (claim.getStatus() != ClaimStatus.REVIEW) {
625	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.OPEN);
626	        }
627	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
628	            throw new ApprovalRefusedException(user);
629	        }
630	        claim.setStatus(ClaimStatus.OPEN);
631	        claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
632	        Claim saved = claims.saveAndFlush(claim);
633	        log(sheetId, user, person, saved);
