639	    /** A steward waives an OPEN or PENDING claim's late charge: it bears none from then on, whatever
640	     *  its overdue state, even one due by a day in a closed period, and CLAIM_WAIVED is written. Anyone
641	     *  else, a claim in any other status, or one already waived, is refused. */
642	    @Transactional
643	    public Claim waive(String sheetId, String user, Long personId, Long id) {
644	        Person person = person(sheetId, personId);
645	        Claim claim = claim(sheetId, personId, id);
646	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
647	            throw new WaiveForbiddenException(user);
648	        }
649	        if (!claim.getStatus().isOpen()) {
650	            throw new WaiveRefusedException("A " + claim.getStatus() + " claim's late charge cannot be waived");
651	        }
652	        if (claim.isWaived()) {
653	            throw new WaiveRefusedException("The claim's late charge is already waived");
654	        }
655	        claim.waive();
656	        Claim saved = claims.saveAndFlush(claim);
657	        record("CLAIM_WAIVED", sheetId, user, person, saved);
658	        return saved;
659	    }
660	
661	    /** Hold an OPEN or PENDING claim, or release it when it is held: it still counts in every total,
662	     *  and CLAIM_HELD or CLAIM_RELEASED is written. A claim
663	     *  in any other status, or one dated in a closed period, is refused. */
664	    @Transactional
665	    public Claim toggleHold(String sheetId, String user, Long personId, Long id) {
666	        Person person = person(sheetId, personId);
667	        Claim claim = claim(sheetId, personId, id);
668	        if (!claim.getStatus().isOpen()) {
669	            throw new HoldRefusedException("A " + claim.getStatus() + " claim cannot be held or released");
670	        }
671	        refuseClosed(sheetId, claim.getDueBy());
672	        claim.toggleHeld();
673	        Claim saved = claims.saveAndFlush(claim);
674	        record(saved.isHeld() ? "CLAIM_HELD" : "CLAIM_RELEASED", sheetId, user, person, saved);
675	        return saved;
676	    }
677	
678	    /** Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date is the sheet's
679	     *  today. A claim in any other status, or one already reminded on the sheet's today, is refused. When
680	     *  the sheet has an escalation gap and the claim's previous reminder was at least that many days before
681	     *  the sheet's today, ESCALATE is written after REMIND, once per claim ever. */
682	    @Transactional
683	    public Claim remind(String sheetId, String user, Long personId, Long id) {
684	        Person person = person(sheetId, personId);
685	        // Lock the sheet first, so two presses on the same day write one reminder.
686	        sheets.lock(sheetId);
687	        Claim claim = claim(sheetId, personId, id);
688	        LocalDate today = sheets.today(sheetId);
689	        if (!claim.getStatus().isOpen()) {
690	            throw new RemindRefusedException("A " + claim.getStatus() + " claim cannot be reminded");
691	        }
692	        if (today.equals(claim.getRemindedOn())) {
693	            throw new RemindRefusedException("The claim was already reminded on " + today);
694	        }
695	        LocalDate previous = claim.getRemindedOn();
696	        Integer gap = settings.escalateAfter(sheetId);
697	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
698	                && !previous.plusDays(gap).isAfter(today);
699	        claim.setRemindedOn(today);
700	        if (escalate) {
701	            claim.setEscalated(true);
702	        }
703	        Claim saved = claims.saveAndFlush(claim);
704	        record("REMIND", sheetId, user, person, saved);
705	        if (escalate) {
706	            record("ESCALATE", sheetId, user, person, saved);
707	        }
708	        return saved;
709	    }
710	
711	    /** Add a proof of a kind (receipt or photo; null when none is chosen, a receipt) to a claim: its
712	     *  proofs count, and its count of the kind, rise by one. A SETTLED or VOID claim, one dated in a
713	     *  closed period, or a kind other than receipt or photo, is refused. */
714	    @Transactional
715	    public Claim addProof(String sheetId, String user, Long personId, Long id, String kind) {
716	        if (kind != null && !ProofKind.valid(kind)) {
717	            throw new ProofRefusedException(kind);
718	        }
719	        Person person = person(sheetId, personId);
720	        Claim claim = claim(sheetId, personId, id);
721	        refuseClosed(sheetId, claim.getDueBy());
722	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
723	            throw new ProofRefusedException(claim.getStatus());
724	        }
725	        claim.addProof(kind);
726	        Claim saved = claims.saveAndFlush(claim);
727	        audit.recordOnCommit(line("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber())
728	                + " proofs=" + saved.getProofs() + (kind != null ? " kind=" + kind : ""));
729	        return saved;
730	    }
731	
732	    /** Comment on a claim in any status: the comment is kept with the user and the sheet's today, and
733	     *  COMMENT_ADDED is written ending with its text. A blank comment is refused. */
734	    @Transactional
735	    public Claim addComment(String sheetId, String user, Long personId, Long id, String text) {
736	        Person person = person(sheetId, personId);
737	        Claim claim = claim(sheetId, personId, id);
738	        String trimmed = text == null ? "" : text.trim();
739	        if (trimmed.isEmpty()) {
740	            throw new CommentRefusedException("A comment cannot be empty");
741	        }
742	        comments.save(new ClaimComment(sheetId, claim.getId(), user, sheets.today(sheetId), trimmed));
743	        audit.recordOnCommit(line("COMMENT_ADDED", sheetId, user, person, claim, claim.getNumber())
744	                + " text=" + trimmed);

