1082	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
1083	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
1084	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
1085	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
1086	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
1087	     *  charges added up. It follows the sheet's today until a statement binds the
1088	     *  claim's due, charge included. A waived claim bears none. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
1089	     *  claim as if it were still OPEN. */
1090	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
1091	            LocalDate asOf) {
1092	        BigDecimal none = BigDecimal.ZERO.setScale(2);
1093	        if (!open || claim.isCorrection() || claim.isWaived()) {
1094	            return none;
1095	        }
1096	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
1097	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
1098	        if (days < 30) {
1099	            return none;
1100	        }
1101	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
1102	        BigDecimal charge = none;
1103	        for (long boundary = 1; boundary <= days / 30; boundary++) {
1104	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
1105	            if (pct.signum() != 0) {
1106	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
1107	            }
1108	        }
1109	        return charge;
1110	    }
