1122	                : rates.rateFor(sheetId, grade, claim.getDate(), claim.getId(), asOf).map(Rate::getRate);
1123	        return inForce
1124	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
