1137	    /** How the OPEN and PENDING claims of people on a grade (the grade in force on the claim's date)
1138	     *  would change were the rate given the grade's rate on every date: how many would show a different
1139	     *  due and the sum of the differences (a due of n/a counts as 0.00). A claim a statement binds keeps
1140	     *  its figure. Nothing is saved. */
1141	    @Transactional(readOnly = true)
1142	    public RatePreview previewRate(String sheetId, String grade, BigDecimal rate) {
1143	        RateOverride override = new RateOverride(grade, rate);
1144	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
1145	                .collect(Collectors.toMap(Person::getId, person -> person));
1146	        int count = 0;
1147	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1148	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
1149	            Person person = byId.get(claim.getPersonId());
1150	            if (person == null || !claim.getStatus().isOpen()
1151	                    || !grade.equals(grades.gradeOn(person.getId(), claim.getDate(), null))) {
1152	                continue;
1153	            }
1154	            BigDecimal now = dueOf(sheetId, person, claim, null);
1155	            BigDecimal then = dueOf(sheetId, person, claim, null, override);
1156	            BigDecimal was = now == null ? BigDecimal.ZERO : now;
1157	            BigDecimal will = then == null ? BigDecimal.ZERO : then;
1158	            if ((now == null) != (then == null) || was.compareTo(will) != 0) {
1159	                count++;
1160	                diff = diff.add(will.subtract(was));
1161	            }
1162	        }
1163	        return new RatePreview(count, diff.setScale(2, RoundingMode.HALF_UP));
1164	    }
