1240	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects,
1241	            Long editedId) {
1242	        if (amount.signum() >= 0) {
1243	            if (corrects != null) {
1244	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
1245	            }
1246	            return;
1247	        }
1248	        if (corrects == null) {
1249	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
1250	        }
1251	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
1252	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
1253	        if (!settled) {
1254	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
1255	        }
1256	        BigDecimal remains = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects).orElseThrow()
1257	                .getAmount();
1258	        for (Claim made : claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId)) {
1259	            if (corrects.equals(made.getCorrects()) && !made.getId().equals(editedId)
1260	                    && made.getStatus() != ClaimStatus.VOID && made.getStatus() != ClaimStatus.DELETED) {
1261	                remains = remains.add(made.getAmount());
1262	            }
1263	        }
1264	        if (amount.negate().compareTo(remains) > 0) {
1265	            throw new CorrectionRefusedException("A correction may not exceed the " + scaled(remains.max(BigDecimal.ZERO))
